Object.assign(window.TEM8_DICTIONARY, {"guest":{"media":{"uk":"media/uk/guest__gb_1.mp3","us":"media/us/guest__us_1.mp3"},"oxford":{"phon":"ɡest","pos":"noun","senses":[{"en":"a person that you have invited to your house or to a particular event that you are paying for","cn":"客人；宾客","ex":{"en":"They only use the dining room when they have guests.","cn":"他们只在有客人时才使用餐厅。"}},{"en":"a person who is staying at a hotel, etc.","cn":"旅客；房客","ex":{"en":"We have accommodation for 500 guests.","cn":"我们有可供 500 位客人住宿的房间。"}},{"en":"a customer in a restaurant","cn":"（餐馆的）客人；食客","lab":"especially North American English","ex":{"en":"Restaurant guests can enjoy superb views across the bay as they dine.","cn":"餐厅的客人可以在用餐时欣赏海湾的壮丽景色。"}},{"en":"a famous person or performer who takes part in a television show, concert or other entertainment","cn":"特别嘉宾；客串演员","ex":{"en":"a guest star/artist","cn":"嘉宾明星／艺术家"}},{"en":"a person who is invited to a particular place or organization, or to speak at a meeting","cn":"特邀嘉宾","ex":{"en":"a guest speaker","cn":"特邀演讲人"}},{"en":"to take part in a television or radio show, a concert, a game, etc. as a visiting or temporary performer or player","cn":"做特邀嘉宾；做客串；做特约演员","ex":{"en":"She guested on several chat shows while visiting Britain.","cn":"她访问英国时做过几个访谈节目的特邀嘉宾。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"客人；宾客","en":"A guest is someone who is visiting you or is at an event because you have invited them.","ex":{"en":"She was a guest at the wedding","cn":"她是参加婚礼的客人。"}},{"pos":"N-COUNT 可数名词","cn":"特邀嘉宾；客串演员","en":"A guest is someone who visits a place or organization or appears on a radio or television show because they have been invited to do so.","ex":{"en":"...a frequent chat show guest","cn":"经常出现在访谈节目中的特邀嘉宾"}},{"pos":"N-COUNT 可数名词","cn":"（旅馆的）客人，房客","en":"A guest is someone who is staying in a hotel. →see usage note at:","ex":{"en":"I was the only hotel guest","cn":"我是宾馆里唯一的住客。"}},{"pos":"VERB 动词","cn":"做特邀嘉宾；做特邀演员；客串","en":"To guest means to take part in a performance or a match as a guest, rather than as a regular member.","ex":{"en":"He guested for one or two League sides","cn":"他在一两支联赛队伍中做过外援。"}},{"pos":"CONVENTION 惯用语","cn":"请便；随便","en":"If you say be my guest to someone, you are giving them permission to do something.","ex":{"en":"If anybody wants to work on this, be my guest.","cn":"如果哪位想干这个，请便。"}}]},"examples":[{"en":"Guests should vacate their rooms by 10.30 a.m.","cn":"旅客应在上午 10:30 以前腾出房间。"},{"en":"She guested on several chat shows while visiting Britain.","cn":"她访问英国时做过几个访谈节目的特邀嘉宾。"}]},"guided":{"media":{"uk":"media/uk/guided__gb_1.mp3","us":"media/us/guided__us_1.mp3"},"oxford":{"phon":"ˈɡaɪdɪd","pos":"adjective","senses":[{"en":"that is led by somebody who works as a guide","cn":"有指导的；有向导的；有导游的","ex":{"en":"a guided tour/walk","cn":"有导游的观光／步行观光"}}]},"examples":[{"en":"a guided tour/walk","cn":"有导游的观光/步行观光"}],"base":"guide"},"guilt":{"oxford":{"phon":"ɡɪlt","pos":"noun","senses":[{"en":"the unhappy feelings caused by knowing or thinking that you have done something wrong","cn":"内疚；悔恨","ex":{"en":"She had feelings of guilt about leaving her children and going to work.","cn":"她因离开自己的孩子去工作而感到内疚。"}},{"en":"the fact that somebody has done something illegal","cn":"犯罪；罪行；有罪","ex":{"en":"His guilt was proved beyond all doubt by the prosecution.","cn":"他的罪行已被控方证实确凿无疑。"}},{"en":"blame or responsibility for doing something wrong or for something bad that has happened","cn":"罪责；责任；罪过","ex":{"en":"The investigation will try to find out where the guilt for the disaster really lies.","cn":"此调查将尽力查出灾难的真正责任所在。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"内疚；悔恨；负罪感","en":"Guilt is an unhappy feeling that you have because you have done something wrong or think that you have done something wrong.","ex":{"en":"Her emotions had ranged from anger to guilt in the space of a few seconds","cn":"几秒钟的时间里，她经历了从愤怒到内疚的情感变化。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"犯罪；罪行；有罪","en":"Guilt is the fact that you have done something wrong or illegal.","ex":{"en":"The trial is concerned only with the determination of guilt according to criminal law","cn":"依照刑法规定，审判仅涉及定罪。"}}]},"media":{"uk":"media/uk/guilt__gb_1.mp3","us":"media/us/guilt__us_1.mp3"},"examples":[{"en":"She had feelings of guilt about leaving her children and going to work.","cn":"她因离开自己的孩子去工作而感到内疚。"},{"en":"The investigation will try to find out where the guilt for the disaster really lies.","cn":"此调查将尽力查出灾难的真正责任所在。"}]},"guarded":{"media":{"uk":"media/uk/guarded__gb_1.mp3","us":"media/us/guarded__us_1.mp3"},"oxford":{"phon":"ˈɡɑːdɪd","pos":"adjective","senses":[{"en":"careful; not showing feelings or giving much information","cn":"谨慎的；有保留的；不明确表态的","ex":{"en":"a guarded reply","cn":"谨慎的回答"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"谨慎的；小心在意的；警惕的","en":"If you describe someone as guarded, you mean that they are careful not to show their feelings or give away information.","ex":{"en":"The boy gave him a guarded look","cn":"那个男孩充满戒心地瞧了他一眼。"}}]},"examples":[{"en":"They gave the news a guarded welcome (= did not show great enthusiasm about it).","cn":"他们对这消息表示谨慎的欢迎。"},{"en":"You should be more guarded in what you say to reporters.","cn":"你对记者说话应更谨慎些。"}],"base":"guard"},"guidebook":{"media":{"uk":"media/uk/guidebook__gb_1.mp3","us":"media/us/guidebook__us_1.mp3"},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"旅行指南","en":"A guidebook is a book that gives tourists information about a town, area, or country."},{"pos":"N-COUNT 可数名词","cn":"指南；手册","en":"A guidebook is a book that gives you information or instructions to help you do or understand something.","ex":{"en":"In 1987 Congressional Quarterly published a series of guidebooks to American politics.","cn":"1987年《国会季刊》出版了一系列美国政治指南读物。"}}]},"examples":[{"en":"travel guidebooks","cn":"旅游手册"}],"oxford":{"phon":"ˈɡaɪdbʊk","pos":"noun","senses":[{"en":"a book that gives information about a place for travellers or tourists","cn":"旅游指南（或手册）","ex":{"en":"a guidebook to Switzerland","cn":"瑞士旅游指南"}}]}},"guide":{"media":{"uk":"media/uk/guide__gb_1.mp3","us":"media/us/guide__us_1.mp3"},"oxford":{"phon":"ɡaɪd","pos":"noun","senses":[{"en":"a person who shows other people the way to a place, especially somebody employed to show tourists around interesting places","cn":"导游；向导","sc":"person","ex":{"en":"Our tour guide showed us around the old town.","cn":"导游领着我们转遍了整个古镇。"}},{"en":"a person who advises you on how to live and behave","cn":"指导者；指引者","sc":"person","ex":{"en":"A guru is the spiritual guide of his students.","cn":"导师是学生的精神导师。"}},{"en":"a book, magazine, app, etc. that gives you information, help or instructions about something","cn":"指南；手册","sc":"book/magazine","ex":{"en":"Let's have a look at the TV guide and see what's on.","cn":"咱们看一下节目表，好知道电视上在放些什么。"}},{"en":"a book that gives information about a place for travellers or tourists","cn":"旅游指南（或手册）","sc":"book/magazine","ex":{"en":"He has written a number of travel guides.","cn":"他写了几本旅游指南。"}},{"en":"something that gives you enough information to be able to make a decision about something or form an opinion","cn":"有指导意义的事物；指导的事物","sc":"something that helps you decide","ex":{"en":"As a rough guide, allow half a cup of rice per person.","cn":"大致定个标准，就是每人半杯米。"}},{"en":"a member of an organization (called the Guides or the Girl Scouts) that is similar to the Scouts and that trains girls in practical skills and does a lot of activities with them, for example camping","cn":"女童子军","lab":"old-fashioned","sc":"girl"},{"en":"to show somebody the way to a place, often by going with them; to show somebody a place that you know well","cn":"给某人领路（或导游）；指引","sc":"show the way","ex":{"en":"It's a dangerous route—you'll need someone to guide you.","cn":"这是一条危险的路线——你需要有人来引导你。"},"pos":"verb"},{"en":"to direct or influence somebody’s behaviour or the development of something","cn":"指导，影响（某人的行为或某事物的发展）","sc":"influence behaviour/development","ex":{"en":"He was always guided by his religious beliefs.","cn":"他的言行总是以自己的宗教信仰为依归。"},"pos":"verb"},{"en":"to explain something to somebody, especially something complicated or difficult","cn":"（向某人）解释，阐明","sc":"explain","ex":{"en":"The health and safety officer will guide you through the safety procedures.","cn":"健康安全专员会向你们讲解安全程序。"},"pos":"verb"},{"en":"to help somebody/something to move in a particular direction; to move something in a particular direction","cn":"搀扶（某人朝…方向）走；（朝…方向）移动（某物）","lab":"figurative","sc":"help somebody/something move","ex":{"en":"She took her arm and guided her across the busy road.","cn":"她挽着她的手臂领她穿过繁忙的公路。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-PROPER-COLL 专有集合名词","cn":"（英国的）女童子军（美国为Girl Scout）","en":"In Britain, the Guides is an organization for girls which teaches them to become practical and independent. The Guides used to be called the Girl Guides. In the United States, there is a similar organization called the Girl Scouts."},{"pos":"N-COUNT 可数名词","cn":"（英国的）女童子军成员","en":"In Britain, a Guide is a girl who is a member of the Guides."}]},"examples":[{"en":"Let's have a look at the TV guide and see what's on.","cn":"咱们看一下节目表，好知道电视上在放些什么。"},{"en":"We hired a local guide to get us across the mountains.","cn":"我们雇了一名当地人做向导带领我们翻山越岭。"}]},"guardian":{"oxford":{"phon":"ˈɡɑːdiən","pos":"noun","senses":[{"en":"a person who protects something","cn":"保护者；守卫者；保卫者","ex":{"en":"Farmers should be guardians of the countryside.","cn":"农民应是农村的守卫者。"}},{"en":"a person who is legally responsible for the care of another person, especially a child whose parents have died","cn":"（尤指双亲已故孩子的）监护人","ex":{"en":"I was left alone to live with my aunt, who became my legal guardian.","cn":"我被孤零零地撇下跟姨妈生活，她成了我的法定监护人。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"监护人","en":"A guardian is someone who has been legally appointed to look after the affairs of another person, for example a child or someone who is mentally ill."},{"pos":"N-COUNT 可数名词","cn":"保护者；护卫者","en":"The guardian of something is someone who defends and protects it.","ex":{"en":"The National Party is lifting its profile as socially conservative guardian of traditional values.","cn":"国家党正在提升自己作为持社会保守立场的传统价值观捍卫者的形象。"}}]},"media":{"uk":"media/uk/guardian__gb_1.mp3","us":"media/us/guardian__us_1.mp3"},"examples":[{"en":"The police are guardians of law and order.","cn":"警察是法律和治安的护卫者。"},{"en":"Farmers should be guardians of the countryside.","cn":"农民应是农村的保卫者。"}]},"gulp":{"media":{"uk":"media/uk/gulp__gb_1.mp3","us":"media/us/gulp__us_1.mp3"},"oxford":{"phon":"ɡʌlp","pos":"verb","senses":[{"en":"to swallow large amounts of food or drink quickly","cn":"狼吞虎咽；大口吞咽；匆匆吞下","g":"[transitive]","ex":{"en":"He gulped down the rest of his tea and went out.","cn":"他把剩下的茶一饮而尽便出去了。"}},{"en":"to swallow, but without eating or drinking something, especially because of a strong emotion such as fear or surprise","cn":"（尤指因害怕或惊讶而）倒吸气","g":"[intransitive]","ex":{"en":"She gulped nervously before trying to answer.","cn":"她紧张地倒吸了一口气才尽力回答。"}},{"en":"to breathe quickly and deeply, because you need more air","cn":"深呼吸；喘大气；大口大口地吸气","g":"[intransitive, transitive]","ex":{"en":"She came up gulping for air.","cn":"她气喘吁吁地走上前来。"}},{"en":"an amount of something that you swallow or drink quickly","cn":"吞饮的量；一大口","ex":{"en":"He took a gulp of coffee.","cn":"他喝了一大口咖啡。"},"pos":"noun"},{"en":"an act of breathing in or of swallowing something","cn":"吸入；吞咽","ex":{"en":"‘Can you start on Monday?’ Amy gave a gulp. ‘Of course,’ she said.","cn":"“你星期一开始可以吗？”埃米吸了一口气。“当然可以。”她说。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"吞食；大口吃；狼吞虎咽","en":"If you gulp something, you eat or drink it very quickly by swallowing large quantities of it at once.","ex":{"en":"She quickly gulped her tea.","cn":"她将茶一饮而尽。"}},{"pos":"VERB 动词","cn":"（因紧张或兴奋）倒吸气","en":"If you gulp, you swallow air, often making a noise in your throat as you do so, because you are nervous or excited.","ex":{"en":"I gulped, and then proceeded to tell her the whole story","cn":"我倒吸了一口气，接着把事情的原委都讲给她听。"}},{"pos":"VERB 动词","cn":"大口大口地吸（气）","en":"If you gulp air, you breathe in a large amount of air quickly through your mouth.","ex":{"en":"She gulped air into her lungs","cn":"她大口大口地吸着气。"}},{"pos":"N-COUNT 可数名词","cn":"吞咽的量；一大口","en":"A gulp of air, food, or drink, is a large amount of it that you swallow at once.","ex":{"en":"I took in a large gulp of air","cn":"我深吸了一大口气。"}},{"pos":"","cn":"","en":"相关词组：gulp down"}]},"examples":[{"en":"‘Can you start on Monday?’ Amy gave a gulp. ‘Of course,’ she said. “","cn":"你星期一开始可以吗？”埃米吸了一口气。“当然可以。”她说。"},{"en":"She gulped nervously before trying to answer.","cn":"她紧张地倒吸了一口气才设法回答。"}]},"guarantee":{"media":{"uk":"media/uk/guarantee__gb_1.mp3","us":"media/us/guarantee__us_1.mp3"},"oxford":{"phon":"ˌɡærənˈtiː","pos":"verb","senses":[{"en":"to promise to do something; to promise something will happen","cn":"保证；担保；保障","ex":{"en":"Basic human rights, including freedom of speech, are now guaranteed.","cn":"现在，包括言论自由在内的基本人权已有了保障。"}},{"en":"to give a written promise to replace or repair a product free if it goes wrong","cn":"提供（产品）保修单（免费掉换或修理有问题的产品）","ex":{"en":"All our electrical goods are fully guaranteed.","cn":"我们所有的电器都有全面质保。"}},{"en":"to make something certain to happen","cn":"使必然发生；确保","ex":{"en":"Tonight's victory guarantees the team's place in the final.","cn":"今晚的胜利确保这个队能进入决赛。"}},{"en":"to be certain that something will happen","cn":"肯定…必然发生","ex":{"en":"You can guarantee (that) the children will start being naughty as soon as they have to go to bed.","cn":"可以肯定孩子一到上床睡觉时就不听话了。"}},{"en":"to agree to be legally responsible for something or for doing something, especially for paying back money that somebody else owes if they cannot pay it back themselves","cn":"承诺对…负法律责任；为…作担保","ex":{"en":"to guarantee a bank loan","cn":"为银行贷款作保"}},{"en":"a formal promise that you will do something or that something will happen","cn":"保证；担保","ex":{"en":"They are demanding certain guarantees before they sign the treaty.","cn":"他们要求得到某些保证后才签署条约。"},"pos":"noun"},{"en":"a written promise given by a company that something you buy will be replaced or repaired without payment if it goes wrong within a particular period","cn":"保修单；保用证书","ex":{"en":"The television comes with a year's guarantee.","cn":"这电视机有一年的保修期。"},"pos":"noun"},{"en":"something that makes something else certain to happen","cn":"起保证作用的事物","ex":{"en":"Career success is no guarantee of happiness.","cn":"事业成功并不是幸福的保证。"},"pos":"noun"},{"en":"money or something valuable that you give or promise to a bank, for example, to make sure that you will do what you have promised","cn":"保证金；抵押品","ex":{"en":"We had to offer our house as a guarantee when getting the loan.","cn":"我们在贷款时不得不拿房子作抵押。"},"pos":"noun"},{"en":"a written promise to pay back money that somebody else owes, or do something that somebody else promised to do, if they cannot do it themselves","cn":"担保书","ex":{"en":"A close relative, usually a parent, can provide a guarantee for the loan.","cn":"近亲属，通常为父母，可为贷款作担保。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"确保；使必然发生","en":"If one thing guarantees another, the first is certain to cause the second thing to happen.","ex":{"en":"Surplus resources alone do not guarantee growth.","cn":"仅有富余的资源并不能确保发展。"}},{"pos":"N-COUNT 可数名词","cn":"保证","en":"Something that is a guarantee of something else makes it certain that it will happen or that it is true.","ex":{"en":"A famous old name on a firm is not necessarily a guarantee of quality","cn":"公司悠久的品牌并不能确保商品的质量。"}},{"pos":"VERB 动词","cn":"保证…必定发生；承诺做；答应提供","en":"If you guarantee something, you promise that it will definitely happen, or that you will do or provide it for someone.","ex":{"en":"Most states guarantee the right to free and adequate education","cn":"大多数州都保障人们免费享受充分教育的权利。"}},{"pos":"N-COUNT 可数名词","cn":"保修单","en":"A guarantee is a written promise by a company to replace or repair a product free of charge if it has any faults within a particular time.","ex":{"en":"Whatever a guarantee says, when something goes wrong, you can still claim your rights from the shop","cn":"不论保修单如何规定，若商品出了问题，消费者仍然可以去商店维护自身权益。"}},{"pos":"VERB 动词","cn":"为…提供质量保证；担保","en":"If a company guarantees its product or work, they provide a guarantee for it.","ex":{"en":"Some builders guarantee their work","cn":"一些建筑公司对其承建工程提供质量保证。"}},{"pos":"N-COUNT 可数名词","cn":"担保金；担保物；抵押品","en":"A guarantee is money or something valuable which you give to someone to show that you will do what you have promised.","ex":{"en":"Males between 18 and 20 had to leave a deposit as a guarantee of returning to do their military service.","cn":"18至20岁的男性必须缴纳一笔保证金，作为回来服兵役的担保。"}}]},"examples":[{"en":"Basic human rights, including freedom of speech, are now guaranteed.","cn":"现在，包括言论自由在内的基本人权已有了保障。"},{"en":"You can guarantee (that) the children will start being naughty as soon as they have to go to bed.","cn":"可以肯定孩子一到上床睡觉时就不听话了。"}]},"gunnel":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a gunwale","cn":"舷缘﹐船舷上缘"}]},"media":{"uk":"media/uk/gunnel__gb_1.mp3","us":"media/us/gunnel__us_1.mp3"},"oxford":{"phon":"ˈɡʌnl","pos":"noun","senses":[{"en":"the upper edge of the side of a boat or small ship","cn":"舷缘（船舷的上缘）"}]}},"guesses":{"lemma":"guess"},"gulf":{"media":{"uk":"media/uk/gulf__gb_1.mp3","us":"media/us/gulf__us_1.mp3"},"oxford":{"phon":"ɡʌlf","pos":"noun","senses":[{"en":"a large area of sea that is partly surrounded by land","cn":"海湾","g":"[countable]","ex":{"en":"the Gulf of Mexico","cn":"墨西哥湾"}},{"en":"the Persian Gulf, the area of sea between the Arabian peninsula and Iran","cn":"波斯湾","g":"[singular]"},{"en":"a large difference between two people or groups in the way that they think, live or feel","cn":"分歧；鸿沟；隔阂","g":"[countable, usually singular]","ex":{"en":"The gulf between rich and poor is enormous.","cn":"贫富悬殊。"}},{"en":"a wide deep opening in the ground","cn":"（地面的）裂口，深坑，沟壑","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-PROPER 专有名词","cn":"波斯湾；阿拉伯海湾；海湾地区","en":"The Gulf is used to refer to the Arabian Gulf, the Persian Gulf and the surrounding countries.","ex":{"en":"...the Gulf crisis.","cn":"海湾危机"}}]},"examples":[{"en":"The gulf between rich and poor is enormous.","cn":"贫富悬殊。"},{"en":"the Gulf States (= the countries with coasts on the Gulf)","cn":"海湾国家"}]},"guardians":{"lemma":"guardian"},"guard":{"oxford":{"phon":"ɡɑːd","pos":"noun","senses":[{"en":"a person, such as a soldier, a police officer or a prison officer, who protects a place or people, or prevents prisoners from escaping","cn":"卫兵；警卫员；看守","g":"[countable]","sc":"people who protect","ex":{"en":"prison/border guards","cn":"监狱看守；边防卫士"}},{"en":"the act or duty of protecting property, places or people from attack or danger; the act or duty of preventing prisoners from escaping","cn":"警戒；保卫；保护；看守","g":"[uncountable]","sc":"people who protect","ex":{"en":"a sentry on guard (= at his or her post, on duty)","cn":"执勤哨兵"}},{"en":"a group of people, such as soldiers or police officers, who protect somebody/something","cn":"（统称）卫兵，警卫，看守","g":"[countable + singular or plural verb]","sc":"people who protect","ex":{"en":"the captain of the guard","cn":"卫队长"}},{"en":"(in the UK and some other countries) special regiments of soldiers whose original duty was to protect the king or queen","cn":"（英国和其他一些国家的）禁军，御林军，近卫军","g":"[plural]","sc":"people who protect","ex":{"en":"the Scots Guards","cn":"苏格兰卫队"}},{"en":"something that covers a part of a person’s body or a dangerous part of a machine to prevent injury","cn":"防护罩；防护装置；防护用品","g":"[countable]","sc":"against injury","ex":{"en":"All players wear helmets and face guards.","cn":"所有球员都戴头盔和面罩。"}},{"en":"conductor (= a person who is in charge of a train and travels with it, but does not drive it)","cn":"列车长","g":"[countable]","lab":"British English, becoming old-fashioned，，","sc":"on train"},{"en":"a position you take to defend yourself, especially in a sport such as boxing or fencing","cn":"防御姿势","g":"[uncountable]","lab":"figurative","sc":"in boxing/fencing","ex":{"en":"to drop/keep up your guard","cn":"放弃／保持防御姿势"}},{"en":"one of the two players on a basketball team who are mainly responsible for staying close to players of the other team to stop them from scoring","cn":"后卫","g":"[countable]","sc":"in basketball"},{"en":"one of the two players on an American football team who play either side of the centre forward","cn":"（中锋两侧的）哨锋","g":"[countable]","sc":"in American football"},{"en":"to protect property, places or people from attack or danger","cn":"警卫；守卫；保卫","lab":"figurative","ex":{"en":"Armed officers guarded the entrance.","cn":"武装人员把守着入口。"},"pos":"verb"},{"en":"to prevent prisoners from escaping","cn":"看守，监视（囚犯）","ex":{"en":"The prisoners were guarded by soldiers.","cn":"犯人由士兵看守。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"守卫；护卫；警卫","en":"If you guard a place, person, or object, you stand near them in order to watch and protect them.","ex":{"en":"Gunmen guarded homes near the cemetery with shotguns","cn":"持枪者手持猎枪守卫着墓地附近的房子。"}},{"pos":"VERB 动词","cn":"看守；监视","en":"If you guard someone, you watch them and keep them in a particular place to stop them from escaping.","ex":{"en":"Marines with rifles guarded them","cn":"手持步枪的海军陆战队士兵监视着他们。"}},{"pos":"N-COUNT 可数名词","cn":"卫兵；警卫员；看守","en":"A guard is someone such as a soldier, police officer, or prison officer who is guarding a particular place or person.","ex":{"en":"The prisoners overpowered their guards and locked them in a cell.","cn":"囚犯们制服了监狱看守，并将他们锁进了牢房。"}},{"pos":"N-SING-COLL 单数集合名词","cn":"（一队）卫兵；（一队）警卫","en":"A guard is a specially organized group of people, such as soldiers or policemen, who protect or watch someone or something.","ex":{"en":"We have a security guard around the whole area","cn":"我们在该地区各处部署了保安。"}},{"pos":"N-COUNT 可数名词","cn":"列车长","en":"On a train, a guard is a person whose job is to travel on the train in order to help passengers, check tickets, and make sure that the train travels safely and on time."},{"pos":"VERB 动词","cn":"保护；保守；遮掩","en":"If you guard some information or advantage that you have, you try to protect it or keep it for yourself.","ex":{"en":"He closely guarded her identity.","cn":"他对她的身份守口如瓶。"}},{"pos":"N-COUNT 可数名词","cn":"保护装置；保护罩；保护器","en":"A guard is a protective device which covers a part of someone's body or a dangerous part of a piece of equipment.","ex":{"en":"...the chin guard of my helmet","cn":"我头盔上的下巴保护罩"}},{"pos":"N-IN-NAMES 名称名词","cn":"（英国的）近卫军，禁军，近卫军士兵","en":"Some regiments in the British Army, or the soldiers in them, are referred to as Guards.","ex":{"en":"...the Grenadier Guards.","cn":"英国近卫步兵团"}},{"pos":"PHRASE 短语","cn":"乘（人）不备；使猝不及防","en":"If someone catches you off guard, they surprise you by doing something you do not expect. If something catches you off guard, it surprises you by happening when you are not expecting it.","ex":{"en":"Charm the audience and catch them off guard","cn":"吸引观众的注意力，然后给他们来个出其不意。"}},{"pos":"PHRASE 短语","cn":"丧失警惕；放松警惕；不提防","en":"If you lower your guard ,let your guard down or drop your guard, you relax when you should be careful and alert, often with unpleasant consequences.","ex":{"en":"The ANC could not afford to lower its guard until everything had been carried out","cn":"非洲人国民大会在所有事项皆已完成前不敢有丝毫松懈。"}},{"pos":"PHRASE 短语","cn":"派人守卫；安排看守","en":"If you mount guard or if you mount a guard, you organize people to watch or protect a person or place.","ex":{"en":"They've even mounted guard outside the main hotel in the capital","cn":"他们甚至派人在首都的大饭店外面站岗。"}},{"pos":"PHRASE 短语","cn":"警惕；提防","en":"If you are on your guard or on guard, you are being very careful because you think a situation might become difficult or dangerous.","ex":{"en":"The police have questioned him thoroughly, and he'll be on his guard","cn":"警方已经对他进行了详细的盘问，因此他会保持戒备心理。"}},{"pos":"PHRASE 短语","cn":"站岗；值班","en":"If someone is on guard, they are on duty and responsible for guarding a particular place or person.","ex":{"en":"Police were on guard at Barnet town hall.","cn":"警察在巴尼特市政厅值守。"}},{"pos":"PHRASE 短语","cn":"站岗；放哨","en":"If you stand guard, you stand near a particular person or place because you are responsible for watching or protecting them.","ex":{"en":"One young policeman stood guard outside the locked embassy gates.","cn":"一位年轻的警察在大门紧闭的使馆外站岗。"}},{"pos":"PHRASE 短语","cn":"在…看守之下","en":"If someone is under guard, they are being guarded.","ex":{"en":"Three men were arrested and one was under guard in hospital.","cn":"有3人被逮捕，1人在警方监护下送医院治疗。"}},{"pos":"","cn":"","en":"相关词组：guard against"}]},"media":{"uk":"media/uk/guard__gb_1.mp3","us":"media/us/guard__us_1.mp3"},"examples":[{"en":"( figurative ) In spite of the awkward questions the minister never let his guard fall for a moment.","cn":"尽管遇到些令人尴尬的问题，部长从没有丝毫退缩。"},{"en":"The lawyer's apparently innocent question was designed to catch the witness off (his) guard.","cn":"律师看似不经意的问题是为了使证人措手不及。"}]},"guarding":{"lemma":"guard"},"guiding":{"media":{"uk":"media/uk/guiding__gb_1.mp3","us":"media/us/guiding__us_1.mp3"},"oxford":{"phon":"ˈɡaɪdɪŋ","pos":"adjective","senses":[{"en":"giving advice and help; having a strong influence on people","cn":"给予指导的；有影响的","ex":{"en":"She was inexperienced and needed a guiding hand.","cn":"她缺乏经验，需要有人指导。"}}]},"examples":[{"en":"She was inexperienced and needed a guiding hand.","cn":"她缺乏经验，需要有人指导。"},{"en":"a guiding force","cn":"有影响的力量"}],"base":"guide"},"guilty":{"oxford":{"phon":"ˈɡɪlti","pos":"adjective","senses":[{"en":"feeling ashamed because you have done something that you know is wrong or have not done something that you should have done","cn":"感到内疚的；感到惭愧的","ex":{"en":"Matt and Chrissy both looked equally guilty.","cn":"马特和克丽茜看上去同样内疚。"}},{"en":"having done something illegal; being responsible for something bad that has happened","cn":"犯有罪的；有过失的；有罪责的","lab":"especially North American English","ex":{"en":"He pleaded guilty to murder.","cn":"他承认犯有谋杀罪。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"内疚的；感到愧疚的","en":"If you feel guilty, you feel unhappy because you think that you have done something wrong or have failed to do something which you should have done.","ex":{"en":"I feel so guilty, leaving all this to you","cn":"把这些事都留给你去做，我真感到过意不去。"}},{"pos":"ADJ 形容词","cn":"罪恶的","en":"Guilty is used of an action or fact that you feel guilty about. guilty conscience→see: ;","ex":{"en":"Many may be keeping it a guilty secret","cn":"许多人或许保守着这个罪恶的秘密。"}},{"pos":"ADJ 形容词","cn":"犯罪的；有罪的","en":"If someone is guilty of a crime or offence, they have committed that crime or offence.","ex":{"en":"They were found guilty of murder","cn":"他们被判谋杀罪成立。"}},{"pos":"ADJ 形容词","cn":"有过失的","en":"If someone is guilty of doing something wrong, they have done that thing.","ex":{"en":"He claimed Mr Brooke had been guilty of a 'gross error of judgment'","cn":"他宣称布鲁克先生犯有“判断失误的重大过错”。"}}]},"media":{"uk":"media/uk/guilty__gb_1.mp3","us":"media/us/guilty__us_1.mp3"},"examples":[{"en":"We've all been guilty of selfishness at some time in our lives.","cn":"我们每个人一生中都有过自私自利的过失。"},{"en":"I felt guilty about not visiting my parents more often.","cn":"我因没有常去看望父母而感到内疚。"}]},"guns":{"lemma":"gun"},"gusto":{"media":{"uk":"media/uk/gusto__gb_1.mp3","us":"media/us/gusto__us_1.mp3"},"oxford":{"phon":"ˈɡʌstəʊ","pos":"noun","senses":[{"en":"enthusiasm and energy in doing something","cn":"热情高涨；兴致勃勃","ex":{"en":"They sang with gusto.","cn":"他们兴致勃勃地唱歌。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（做某事的）热情，兴致，精力","en":"If you do something with gusto, you do it with energetic and enthusiastic enjoyment.","ex":{"en":"Hers was a minor part, but she played it with gusto.","cn":"她演的是个小角色，但是演得很投入。"}}]},"examples":[{"en":"They sang with gusto.","cn":"他们兴致勃勃地唱歌。"},{"en":"They sang hymns with great gusto.","cn":"他们满怀热情地唱赞美诗。"}]},"guidance":{"media":{"uk":"media/uk/guidance__gb_1.mp3","us":"media/us/guidance__us_1.mp3"},"oxford":{"phon":"ˈɡaɪdns","pos":"noun","senses":[{"en":"help or advice that is given to somebody, especially by somebody older or with more experience","cn":"指导；引导；咨询","ex":{"en":"guidance for teachers on how to use video in the classroom","cn":"为教师提供的课堂录像教学指导"}},{"en":"the process of controlling the direction of a rocket, etc., using electronic equipment","cn":"（火箭等的）制导，导航","ex":{"en":"a missile guidance system","cn":"导弹制导系统"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"指导；引导；咨询","en":"Guidance is help and advice.","ex":{"en":"...an opportunity for young people to improve their performance under the guidance of professional coaches","cn":"年轻人在职业教练的指导下提高成绩的机会"}}]},"examples":[{"en":"Activities all take place under the guidance of an experienced tutor.","cn":"所有活动都在经验丰富的导师指导下进行。"},{"en":"guidance for teachers on how to use video in the classroom","cn":"对教师提供的课堂录像教学指导"}]},"guess":{"oxford":{"phon":"ɡes","pos":"verb","senses":[{"en":"to try and give an answer or make a judgement about something without being sure of all the facts","cn":"猜测；估计","g":"[intransitive, transitive]","lab":"British English or formal, North American English，，","ex":{"en":"I don't really know. I'm just guessing.","cn":"我并不知道，我只是猜测。"}},{"en":"to find the right answer to a question or the truth without knowing all the facts","cn":"猜对；猜中；猜到","g":"[transitive, intransitive]","ex":{"en":"She guessed the answer straight away.","cn":"她一下子就猜中了答案。"}},{"en":"used to show that you are going to say something surprising or exciting","cn":"（引出令人惊奇或激动的事）你猜","g":"[transitive]","ex":{"en":"Guess what! He's asked me out!","cn":"你猜怎么着！他约我出去了！"}},{"en":"to suppose that something is true or likely","cn":"我想；我以为","g":"[transitive, intransitive]","lab":"informal","ex":{"en":"I guess (that) you’ll be looking for a new job now.","cn":"我想你现在要找新工作了吧。"}},{"en":"an attempt to give an answer or an opinion when you cannot be certain if you are right","cn":"猜测；猜想","lab":"British English","ex":{"en":"to have/make a guess","cn":"（对某事）作猜测"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"猜；猜想；推测","en":"If you guess something, you give an answer or provide an opinion which may not be true because you do not have definite knowledge about the matter concerned.","ex":{"en":"The suit was faultless: Wood guessed that he was a very successful publisher or a banker","cn":"西装无可挑剔：伍德推测他可能是个相当成功的出版商或银行家。"}},{"pos":"VERB 动词","cn":"猜中；猜对","en":"If you guess that something is the case, you correctly form the opinion that it is the case, although you do not have definite knowledge about it.","ex":{"en":"By now you will have guessed that I'm back in Ireland","cn":"你现在应该已经猜出我回到了爱尔兰了。"}},{"pos":"N-COUNT 可数名词","cn":"猜测；猜想","en":"A guess is an attempt to give an answer or provide an opinion which may not be true because you do not have definite knowledge about the matter concerned.","ex":{"en":"My guess is that the chance that these vaccines will work is zero","cn":"我猜测这些疫苗根本不可能奏效。"}},{"pos":"PHRASE 短语","cn":"大家都拿不准的事","en":"If you say that something is anyone's guess or anybody's guess, you mean that no-one can be certain about what is really true.","ex":{"en":"Just when this will happen is anyone's guess","cn":"谁也说不准这事什么时候会发生。"}},{"pos":"PHRASE 短语","cn":"凭猜测","en":"You say at a guess to indicate that what you are saying is only an estimate or what you believe to be true, rather than being a definite fact.","ex":{"en":"At a guess he's been dead for two days.","cn":"据猜测，他已死了两天。"}},{"pos":"PHRASE 短语","cn":"我想；我认为","en":"You say I guess to show that you are slightly uncertain or reluctant about what you are saying.","ex":{"en":"I guess she thought that was pretty smart","cn":"我想她可能认为那个很漂亮。"}},{"pos":"PHRASE 短语","cn":"让（人）捉摸不定","en":"If someone keeps you guessing, they do not tell you what you want to know.","ex":{"en":"The author's intention is to keep everyone guessing until the bitter end","cn":"这位作家打算把悲惨结局的悬念一直保留到最后。"}},{"pos":"CONVENTION 惯用语","cn":"你猜怎么着；想不到吧","en":"You say guess what to draw attention to something exciting, surprising, or interesting that you are about to say.","ex":{"en":"Guess what, I just got my first part in a movie.","cn":"你猜怎么着，我刚刚得到了自己的第一个电影角色。"}}]},"media":{"uk":"media/uk/guess__gb_1.mp3","us":"media/us/guess__us_1.mp3"},"examples":[{"en":"You would never guess (that) she had problems. She's always so cheerful.","cn":"你怎么也猜不到她有难以解决的问题。她总是那么乐观。"},{"en":"They might be here by 3 — but that's just a rough guess (= not exact).","cn":"他们可能 3 点钟到，不过这只是一个大致的猜测。"}]},"gullible":{"media":{"uk":"media/uk/gullible__gb_1.mp3","us":"media/us/gullible__us_1.mp3"},"oxford":{"phon":"ˈɡʌləbl","pos":"adjective","senses":[{"en":"too willing to believe or accept what other people tell you and therefore easily tricked","cn":"轻信的；易受骗的；易上当的","ex":{"en":"The advertisement is aimed at gullible young women worried about their weight.","cn":"这则广告针对的是担心发胖而易受骗的年轻女性。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"轻信的；易受骗的；易上当的","en":"If you describe someone as gullible, you mean they are easily tricked because they are too trusting.","ex":{"en":"What point is there in admitting that the stories fed to the gullible public were false?","cn":"承认向轻信媒体的公众提供了不实报道有何意义呢？"}}]},"examples":[{"en":"Plastic replicas of the Greek pottery are sold to gullible tourists.","cn":"仿古希腊陶器的塑料复制品被卖给易上当的游客。"}]},"guessed":{"lemma":"guess"},"gun":{"oxford":{"phon":"ɡʌn","pos":"noun","senses":[{"en":"a weapon that is used for firing bullets or shells","cn":"枪；炮","g":"[countable]","ex":{"en":"I have never fired a gun in my life.","cn":"我这辈子从没开过枪。"}},{"en":"a tool that uses pressure to send out a substance or an object","cn":"喷射器；喷枪","g":"[countable]","ex":{"en":"a staple gun","cn":"U 形钉枪"}},{"en":"the signal to begin a race, that is made by firing a special gun, called a starting pistol, into the air","cn":"起跑信号；发令枪声","g":"[singular]"},{"en":"a person who is paid to shoot somebody","cn":"受雇杀人的枪手","g":"[countable]","lab":"informal, especially North American English，，","ex":{"en":"a hired gun","cn":"雇用的枪手"}},{"en":"to run very quickly","cn":"快速运转","g":"[intransitive]","lab":"North American English","ex":{"en":"a line of motorcycles with their engines gunning","cn":"引擎狂转的一队摩托车"},"pos":"verb"},{"en":"to start driving a vehicle very fast","cn":"使（车辆）加速","g":"[transitive]","lab":"North American English","ex":{"en":"He gunned the cab through the red light.","cn":"他猛踩油门，开着出租车闯过了红灯。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"枪；炮","en":"A gun is a weapon from which bullets or other things are fired.","ex":{"en":"He produced a gun and he came into the house","cn":"他掏出枪来，走进房子。"}},{"pos":"N-COUNT 可数名词","cn":"发令枪","en":"A gun or a starting gun is an object like a gun that is used to make a noise to signal the start of a race.","ex":{"en":"The starting gun blasted and they were off.","cn":"发令枪响了，他们冲了出去。"}},{"pos":"VERB 动词","cn":"把…发动起来；给…加大油门；使加速","en":"To gun an engine or a vehicle means to make it start or go faster by pressing on the accelerator pedal.","ex":{"en":"He gunned his engine and drove off.","cn":"他发动引擎，驱车而去。"}},{"pos":"PHRASE 短语","cn":"全力以赴；鼓足干劲","en":"If you come out with guns blazing or with all guns blazing, you put all your effort and energy into trying to achieve something.","ex":{"en":"The company came out with guns blazing.","cn":"公司鼓足了劲要大干一番。"}},{"pos":"PHRASE 短语","cn":"抢先行动；过早地行动","en":"If you jump the gun, you do something before everyone else or before the proper or right time.","ex":{"en":"It wasn't due to be released until September 10, but some booksellers have jumped the gun and decided to sell it early.","cn":"这本书定于9月10号发行，但是一些书商已抢先一步，决定提前销售。"}},{"pos":"PHRASE 短语","cn":"坚持自己的立场；固执己见；一意孤行","en":"If you stick to your guns, you continue to have your own opinion about something even though other people are trying to tell you that you are wrong.","ex":{"en":"He should have stuck to his guns and refused to meet her.","cn":"他本应坚持己见，拒绝与她会面。"}},{"pos":"","cn":"","en":"相关词组：gun down gun for"}]},"media":{"uk":"media/uk/gun__gb_1.mp3","us":"media/us/gun__us_1.mp3"},"examples":[{"en":"He gunned the cab through the red light.","cn":"他猛踩油门，开着出租汽车闯过了红灯。"},{"en":"The champions came out (with) all guns blazing.","cn":"优胜者们神采奕奕地登场亮相。"}]},"guideline":{"oxford":{"phon":"ˈɡaɪdlaɪn","pos":"noun","senses":[{"en":"a set of rules or instructions that are given by an official organization telling you how to do something, especially something difficult","cn":"指导方针；指导原则；行动纲领；准则","g":"[plural]","ex":{"en":"The government has drawn up guidelines for schools during the pandemic.","cn":"政府为疫情期间的学校制定了指导方针。"}},{"en":"something that can be used to help you make a decision or form an opinion","cn":"参考","g":"[countable]","ex":{"en":"The figures are a useful guideline when buying a house.","cn":"买房时这些数据很有参考价值。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"指导方针；指导原则；准则","en":"If an organization issues guidelines on something, it issues official advice about how to do it.","ex":{"en":"The government should issue clear guidelines on the content of religious education","cn":"政府应当就宗教教育的内容颁布明确的指导方针。"}},{"pos":"N-COUNT 可数名词","cn":"参考","en":"A guideline is something that can be used to help you plan your actions or to form an opinion about something.","ex":{"en":"The effects of the sun can be significantly reduced if we follow certain guidelines","cn":"如果我们遵循某些建议，日晒的影响会大大降低。"}}]},"media":{"uk":"media/uk/guideline__gb_1.mp3","us":"media/us/guideline__us_1.mp3"},"examples":[{"en":"The government has drawn up guidelines on the treatment of the mentally ill.","cn":"政府制订了对待精神病人的指导方针。"},{"en":"The figures are a useful guideline when buying a house.","cn":"买房时这些数据很有参考价值。"}]},"guidebooks":{"lemma":"guidebook","media":{"uk":"media/uk/guidebook__gb_1.mp3","us":"media/us/guidebook__us_1.mp3"}},"guides":{"lemma":"guide"},"guests":{"lemma":"guest"},"guaranteeing":{"lemma":"guarantee"},"guaranteed":{"lemma":"guarantee"},"guarantees":{"lemma":"guarantee"},"gunfire":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"炮火；炮击","en":"Gunfire is the repeated shooting of guns.","ex":{"en":"The sound of gunfire and explosions grew closer.","cn":"枪炮声和爆炸声越来越近。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the noise made by a gun when it is fired","cn":""},{"en":"the sound made by several guns being fired, especially in a war","cn":""},{"en":"an attempt to shoot someone or something","cn":""}]},"collocations":{"phrases":["ADJ. heavy, intense | scattered, sporadic | indiscriminate Seventy protesters were killed by indiscriminate gunfire. | distant | automatic W","QUANT. burst A burst of gunfire echoed across the square.","VERB + GUNFIRE hear | spray sb/sth with The terrorists boarded the bus and sprayed the passengers with gunfire. | be hit/wounded by A convoy","GUNFIRE + VERB break out Heavy gunfire broke out in the capital last night. | echo","PHRASES the crack/crackle/rattle/sound of gunfire, an exchange of gunfire They were killed in an exchange of gunfire between riot police and"]},"media":{"uk":"media/ldoce/hwd/bre/e/gunfire0205.mp3","us":"media/ldoce/hwd/ame/3/gunfire.mp3"},"examples":[{"en":"I could hear gunfire.","cn":"我可以听到炮声。"},{"en":"an exchange of gunfire with the police","cn":"与警方的交火"}],"oxford":{"phon":"ˈɡʌnfaɪə(r)","pos":"noun","senses":[{"en":"the repeated firing of guns; the sound of guns firing","cn":"（接连不断的）炮火，炮火声","ex":{"en":"an exchange of gunfire with the police","cn":"与警方的交火"}}]}},"gull":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（海）鸥","en":"A gull is a common sea bird."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large common black and white sea bird that lives near the sea","cn":"海鸥"}]},"vocab":{"pos":"1 n 2 n v","senses":[{"en":"You know those birds that hang out by the ocean, and grab your sandwich if you aren't paying attention? Those are gulls , also known as sea gulls. Gulls are found in every continent, including Antarctica."}]},"media":{"img":["media/ldoce/img/gull.jpg","media/thumb/gull.jpg"],"uk":"media/ldoce/hwd/bre/7/gull0205.mp3","us":"media/ldoce/hwd/ame/c/gull1.mp3"},"oxford":{"phon":"ɡʌl","pos":"noun","senses":[{"en":"a seabird with long wings and usually white and grey or black feathers. There are several types of gull.","cn":"海鸥","ex":{"en":"a black-headed gull","cn":"黑头鸥"}}]}},"gut":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"内脏","en":"A person's or animal's guts are all the organs inside them.","ex":{"en":"By the time they finish, the crewmen are standing ankle-deep in fish guts.","cn":"到他们完工时，船员站的地方鱼内脏已堆至脚踝。"}},{"pos":"VERB 动词","cn":"取出（动物或鱼）的内脏（以备烹饪）","en":"When someone guts a dead animal or fish, they prepare it for cooking by removing all the organs from inside it.","ex":{"en":"It is not always necessary to gut the fish prior to freezing.","cn":"冷冻鱼之前并不总是需要先把内脏掏空。"}},{"pos":"N-SING 单数名词","cn":"肠；消化道","en":"The gut is the tube inside the body of a person or animal through which food passes while it is being digested."},{"pos":"N-UNCOUNT 不可数名词","cn":"勇气；胆量；决心","en":"Guts is the will and courage to do something which is difficult or unpleasant, or which might have unpleasant results.","ex":{"en":"The new Chancellor has the guts to push through unpopular tax increases","cn":"新总理有勇气推动不受欢迎的增税方案获得通过。"}},{"pos":"N-SING 单数名词","cn":"直觉；本能；感性","en":"A gut feeling is based on instinct or emotion rather than reason.","ex":{"en":"Let's have your gut reaction to the facts as we know them.","cn":"请告诉我们你对我们所了解的这些事实的本能反应。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指大而凸出的）肚子","en":"You can refer to someone's stomach as their gut, especially when it is very large and sticks out.","ex":{"en":"His gut sagged out over his belt.","cn":"他肚子上的赘肉堆在皮带上方。"}},{"pos":"N-PLURAL 复数名词","cn":"核心成分；本质；实质","en":"The guts of something, for example a subject or a machine, are the key elements of it, which make it work.","ex":{"en":"She has a reputation for getting at the guts of a subject and never pulling her punches","cn":"她以善抓问题实质、说话一针见血著称。"}},{"pos":"VERB 动词","cn":"损毁（建筑物）的内部","en":"To gut a building means to destroy the inside of it so that only its outside walls remain.","ex":{"en":"Over the weekend, a firebomb gutted a building where 60 people lived","cn":"本周，一颗燃烧弹炸毁了一栋有60位居民的楼房。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（用于制作球拍的网线、小提琴弦等的）肠线","en":"Gut is string made from part of the stomach of an animal. Traditionally, it is used to make the strings of sports rackets or musical instruments such as violins."},{"pos":"PHRASE 短语","cn":"努力（做…)","en":"To bust a gut means to work very hard trying to achieve something.","ex":{"en":"You can bust a gut sixteen hours a day, seven days a week, but if your product is lousy, you've wasted your time.","cn":"你可以一周7天、一天16小时地拼命劳作，但是如果产品质量低劣，你就白费时间了。"}},{"pos":"PHRASE 短语","cn":"对…恨之入骨","en":"If you hate someone's guts, you dislike them very much indeed.","ex":{"en":"We hate each other's guts.","cn":"我们彼此恨之入骨。"}},{"pos":"PHRASE 短语","cn":"告密；把所知和盘托出；倾诉心里话","en":"If someone spills their guts, they tell you everything about something secret or private.","ex":{"en":"People call in and just spill their guts about whatever's bothering them on the job or in a relationship.","cn":"人们打进电话，就是要将工作或感情上的所有困扰倾诉出来。"}},{"pos":"PHRASE 短语","cn":"拼命工作；拼命干活","en":"If you say that you are working your guts out or slogging your guts out, you are emphasizing that you are working as hard as you can.","ex":{"en":"Most have worked their guts out and made sacrifices.","cn":"大部分人都拼命工作，作出了很大的牺牲。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man who has a paunch has a large stomach","cn":""},{"en":"a round stomach that sticks out at the front, especially when this is the result of eating or drinking too much","cn":""},{"en":"a fat stomach caused by drinking too much beer","cn":""}]},"collocations":{"phrases":["ADV. completely The hotel was completely gutted by fire last year."]},"media":{"uk":"media/ldoce/hwd/bre/9/gut_v0205.mp3","us":"media/ldoce/hwd/ame/e/gut1.mp3"},"examples":[{"en":"He doesn't have the guts to walk away from a well-paid job.","cn":"他没胆量辞去一份报酬优厚的工作。"},{"en":"I slogged my guts out for the exam.","cn":"我为这次考试命都豁出去了。"}],"oxford":{"phon":"ɡʌt","pos":"noun","senses":[{"en":"the tube in the body through which food passes when it leaves the stomach","cn":"肠道；消化道","g":"[countable]","ex":{"en":"It can take up to 72 hours for food to pass through the gut.","cn":"食物需经多达72小时才能通过消化道。"}},{"en":"the organs in and around the stomach, especially in an animal","cn":"（尤指动物的）内脏","g":"[plural]","ex":{"en":"I'll only cook fish if the guts have been removed.","cn":"鱼若已收拾干净，我只需烧一下即可。"}},{"en":"a person’s stomach, especially when it is large","cn":"（尤指大的）胃，肚子","g":"[countable]","lab":"informal","ex":{"en":"Have you seen the gut on him!","cn":"你看到他那大肚子了吧！"}},{"en":"the courage and strength of mind that it takes to do something difficult or unpleasant","cn":"勇气；胆量；决心；魄力","g":"[plural]","lab":"informal","ex":{"en":"He doesn't have the guts to walk away from a well-paid job.","cn":"他没胆量辞去一份报酬优厚的工作。"}},{"en":"the place where your natural feelings that make you react in a particular way are thought to be","cn":"内心；直觉；本能","g":"[countable, usually plural]","ex":{"en":"I had a feeling in my guts that something was wrong.","cn":"我本能地感到出了事。"}},{"en":"the most important part of something","cn":"核心；实质；要点","g":"[plural]","ex":{"en":"the guts of the problem","cn":"问题的实质"}},{"en":"thin strong string made from animals' intestines and used in making musical instruments, tennis rackets and medical equipment","cn":"肠线（用于制作乐器、球拍的弦和医疗用品）","g":"[uncountable]"},{"en":"to destroy the inside or contents of a building or room","cn":"损毁（建筑物或房屋的）内部","g":"[usually passive]","ex":{"en":"The hotel was completely gutted by fire last year.","cn":"该旅馆去年被大火完全烧空了。"},"pos":"verb"},{"en":"to remove the organs from inside a fish or an animal to prepare it for cooking","cn":"取出…的内脏（以便烹饪）","ex":{"en":"The fish was already cleaned and gutted.","cn":"鱼已经清洗干净，去内脏了。"},"pos":"verb"},{"en":"based on feelings and emotions rather than thought and reason","cn":"以感情为基础的；非理性的；本能的","ex":{"en":"a gut feeling/reaction","cn":"本能的感觉／反应"},"pos":"adjective"}]}},"guerrilla":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"游击队员","en":"A guerrilla is someone who fights as part of an unofficial army, usually against an official army or police force.","ex":{"en":"The guerrillas threatened to kill their hostages.","cn":"这些游击队员威胁要杀死人质。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who takes part in or supports an attempt to change the government by using violence","cn":""},{"en":"someone who fights in an unofficial military group, trying to remove their country's existing government, especially by making surprise military attacks","cn":""},{"en":"someone who is fighting to try to remove their country's existing government - use this if you think that this is the right thing to do","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If your brother says he’s going to become a guerrilla , don't worry, he's not planning to become a hairy animal. Guerrilla fighters band together in a small underground army, usually trying to overcome a larger and more organized force."}]},"collocations":{"phrases":["ADJ. armed | urban Urban guerrillas detonated a car bomb in front of the company's headquarters. | communist, opposition, right-wing, separa","GUERRILLA + NOUN army, band, force, group, movement, organization, unit | commander, fighter, leader | activity, attack, campaign, offensive"]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdeguerrilla.mp3","us":"media/ldoce/hwd/ame/6/laadguerrilla.mp3"},"examples":[{"en":"guerrilla marketing (= marketing that uses unusual methods in order to achieve the greatest effect for the smallest amount of money)","cn":"游击营销（用不一般的方式以最少金钱取得最大成效）"},{"en":"Guerrilla actors took to the streets in army fatigues to protest against the war.","cn":"非正式演员穿着军服走上街头举行反战示威。"}],"oxford":{"phon":"ɡəˈrɪlə","pos":"noun","senses":[{"en":"a member of a small group of soldiers who are not part of an official army and who fight against official soldiers, usually to try to change the government","cn":"游击队员","ex":{"en":"urban guerrillas (= those who fight in towns)","cn":"城市游击队员"}},{"en":"organized in an informal way and without official permission or approval","cn":"游击的；非正式的；没有官方认可的","ex":{"en":"Guerrilla actors took to the streets in army fatigues to protest against the war.","cn":"非正式演员穿着士兵服走上街头举行反战示威。"},"pos":"adjective"}]}},"guy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男人；小伙子；家伙","en":"A guy is a man.","ex":{"en":"I was working with a guy from Manchester.","cn":"我与一个来自曼彻斯特的小伙子一起工作。"}},{"pos":"N-VOC; N-PLURAL 称呼名词；复数名词","cn":"（美国英语）伙计们，兄弟们，姐妹们","en":"Americans sometimes address a group of people, whether they are male or female, as guys or you guys.","ex":{"en":"Hi, guys. How are you doing?","cn":"嗨，伙计们，大家还好吧？"}},{"pos":"N-COUNT 可数名词","cn":"同guy rope","en":"A guy is the same as a guy rope ."},{"pos":"N-COUNT 可数名词","cn":"盖伊模拟像（英国庆祝篝火之夜焚烧的身着古装的人像）","en":"In Britain, a guy is a model of a man that is made from old clothes filled with straw or paper. Guys are burned on bonfires as part of the celebrations for Guy Fawkes Night."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an adult male human","cn":""},{"en":"a man","cn":"男人﹐家伙"},{"en":"a man – used as a very polite way of talking about a man","cn":""}]},"vocab":{"pos":"1 n 2 n v 3 v","senses":[{"en":"When you're casually talking about a man or a boy, you can call him a guy . It's an informal way to refer to a person, especially a male."}]},"collocations":{"phrases":["ADJ. decent, friendly, funny, good, great, nice, sweet, wonderful | bad | ordinary, regular Neighbours described the killer as &lsquo;just a"]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdeguy.mp3","us":"media/ldoce/hwd/ame/5/guy1.mp3"},"examples":[{"en":"At the end of the film the bad guy gets shot.","cn":"这坏蛋在影片结尾时被击毙。"},{"en":"Come on, you guys, let's get going!","cn":"快点，伙计们，咱们走吧！"}],"oxford":{"phon":"ɡaɪ","pos":"noun","senses":[{"en":"a man","cn":"男人；小伙子；家伙","g":"[countable]","lab":"informal","ex":{"en":"a big/little guy","cn":"大个子；小个子"}},{"en":"a group of people of either sex","cn":"一群男人（或女人）；伙计们；兄弟（或姐妹）们","g":"[plural]","lab":"informal","ex":{"en":"Come on, you guys, let's get going!","cn":"快点，伙计们，咱们走吧！"}},{"en":"(in the UK) a model of a man dressed in old clothes that is burned on a bonfire on 5 November during the celebrations for Bonfire Night","cn":"盖伊模拟像（英国每年 11 月 5 日庆祝篝火之夜焚烧的身着古装的人体模型）","g":"[countable]"},{"en":"a rope used to keep a pole or tent in a secure position","cn":"（立杆子或架帐篷用的）支索，牵索，拉索","g":"[countable]"},{"en":"a first name for boys","cn":"盖伊（男子名）","pos":""}]}},"guesswork":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"猜测；推测","en":"Guesswork is the process of trying to guess or estimate something without knowing all the facts or information.","ex":{"en":"The question of who planted the bomb remains a matter of guesswork.","cn":"到底是谁安放了炸弹依然只是猜测。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an attempt to guess something","cn":""},{"en":"an opinion about the value, size, speed etc of something that is formed partly by calculating and partly by guessing","cn":""},{"en":"when you try to understand something or find the answer to something by guessing, because you do not have all the information you need","cn":""}]},"collocations":{"phrases":["ADJ. pure | informed, inspired Their results owe more to informed guesswork than to actual knowledge.","VERB + GUESSWORK be based on Their price estimates are based on pure guesswork.","PHRASES a matter of guesswork Long-term forecasts were largely a matter of guesswork."]},"media":{"uk":"media/ldoce/hwd/bre/1/guesswork0205.mp3","us":"media/ldoce/hwd/ame/9/guesswork.mp3"},"examples":[{"en":"It was pure guesswork on our part.","cn":"这纯属我们的猜测。"},{"en":"There’s a lot of guesswork in these calculations.","cn":"这些计算中有多处都是推测。"}],"oxford":{"phon":"ˈɡeswɜːk","pos":"noun","senses":[{"en":"the process of trying to find an answer by guessing when you do not have enough information to be sure","cn":"猜想；猜测","ex":{"en":"It was pure guesswork on our part.","cn":"这纯属我们的猜测。"}}]}},"guitar":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"吉他；六弦琴","en":"A guitar is a musical instrument with six strings and a long neck. You play the guitar by plucking or strumming the strings."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a musical instrument usually with six strings that you play by pulling the strings with your fingers or with a plectrum (= small piece of plastic, metal etc )","cn":"吉他"}]},"collocations":{"phrases":["ADJ. acoustic, electric | bass, lead, rhythm | classical, jazz, rock | 6/12-string","VERB + GUITAR strum (on) As she sang, she strummed her guitar. | tune (up) | build, make","GUITAR + NOUN string | lick, riff •"]},"media":{"img":["media/ldoce/img/guitar.jpg"],"uk":"media/ldoce/hwd/bre/a/guitar0205.mp3","us":"media/ldoce/hwd/ame/4/guitar.mp3"},"examples":[{"en":"an acoustic/an electric/a classical, etc. guitar","cn":"原声吉他、电吉他、古典吉他等"},{"en":"She plays guitar in a band.","cn":"她在乐队里弹奏吉他。"}],"oxford":{"phon":"ɡɪˈtɑː(r)","pos":"noun","senses":[{"en":"a musical instrument that usually has six strings and that you play with your fingers or with a plectrum","cn":"吉他","ex":{"en":"an acoustic/electric guitar","cn":"原声吉他；电吉他"}}]}},"gust":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一阵强风；一阵狂风","en":"A gust is a short, strong, sudden rush of wind.","ex":{"en":"A gust of wind drove down the valley","cn":"一阵狂风刮过山谷。"}},{"pos":"VERB 动词","cn":"猛刮；劲吹","en":"When the wind gusts, it blows with short, strong, sudden rushes.","ex":{"en":"The wind gusted again","cn":"风再次猛烈地刮了起来。"}},{"pos":"N-COUNT 可数名词","cn":"（感情的）迸发，爆发","en":"If you feel a gust of emotion, you feel the emotion suddenly and intensely.","ex":{"en":"...a small gust of pleasure.","cn":"短暂的一阵欢喜"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden strong movement of wind, air, rain etc","cn":"一阵狂风﹔一阵暴雨"},{"en":"a sound of loud laughter","cn":"一阵狂笑"},{"en":"if the wind gusts, it blows strongly with sudden short movements 〔","cn":"狂风〕一阵阵劲吹"}]},"vocab":{"pos":"n","senses":[{"en":"A gust is a strong, short burst of air. If you're walking around on a brisk, cold day, hold on to your papers tightly — a gust of wind could sweep in and send your notes flying into the air."}]},"collocations":{"phrases":["ADJ. great | little | strong | sudden | occasional","PREP. ~ of a sudden gust of wind","PHRASES blow/come in gusts The wind came in great gusts off the Pacific."]},"media":{"uk":"media/ldoce/hwd/bre/2/gust_n0205.mp3","us":"media/ldoce/hwd/ame/e/gust1.mp3"},"examples":[{"en":"winds gusting up to 60 mph","cn":"风速达每小时 60 英里的狂风"},{"en":"A gust of wind blew his hat off.","cn":"一阵狂风把他的帽子刮掉了。"}],"oxford":{"phon":"ɡʌst","pos":"noun","senses":[{"en":"a sudden strong increase in the amount and speed of wind that is blowing","cn":"一阵强风；一阵狂风","ex":{"en":"A gust of wind blew his hat off.","cn":"一阵狂风把他的帽子刮掉了。"}},{"en":"a sudden strong expression of emotion","cn":"（感情的）迸发，爆发，发作","ex":{"en":"a gust of laughter","cn":"一阵笑声"}},{"en":"to suddenly blow very hard","cn":"猛刮；劲吹","ex":{"en":"winds gusting up to 60 mph","cn":"风速达每小时 60 英里的狂风"},"pos":"verb"}]}},"gum":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"口香糖","en":"Gum is a substance, usually tasting of mint, which you chew for a long time but do not swallow."},{"pos":"N-COUNT 可数名词","cn":"牙龈；齿龈；牙床","en":"Your gums are the areas of firm, pink flesh inside your mouth, which your teeth grow out of.","ex":{"en":"The toothbrush gently removes plaque without damaging the gums.","cn":"这种牙刷可以温和去除牙菌斑而不损伤齿龈。"}},{"pos":"N-MASS 物质名词","cn":"黏胶；黏合剂","en":"Gum is a type of glue that is used to stick two pieces of paper together.","ex":{"en":"He was holding up a pound note that had been torn in half and stuck together with gum.","cn":"他举着一张被撕成两半后又用胶粘在一起的一英镑的钞票。"}},{"pos":"ADJ 形容词","cn":"黏合的","en":"If two things are gummed together, they are stuck together.","ex":{"en":"It is a mild infection in which a baby's eyelashes can become gummed together.","cn":"这是一种轻微感染，会导致婴儿睫毛粘在一起。"}},{"pos":"N-MASS 物质名词","cn":"树胶；树脂","en":"Gum is a sticky substance which comes from the eucalyptus tree or from various other trees and shrubs."},{"pos":"","cn":"","en":"相关词组：gum up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"your gums are the two areas of firm pink flesh at the top and bottom of your mouth, in which your teeth are fixed","cn":"齿龈﹐牙龈"},{"en":"chewing gum","cn":"口香糖"},{"en":"a type of glue used to stick light things such as paper together","cn":"黏胶"}]},"collocations":{"phrases":["ADJ. lower, upper | toothless The old man smiled to reveal toothless gums. | bleeding, swollen","GUM + NOUN disease"]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdegum.mp3","us":"media/ldoce/hwd/ame/3/gum1.mp3"},"examples":[{"en":"A large address label was gummed to the package.","cn":"包装袋上贴着一大张地址签条。"},{"en":"fruit gums","cn":"水果软糖"}],"oxford":{"phon":"ɡʌm","pos":"noun","senses":[{"en":"either of the areas of flesh in the mouth to which the teeth are attached","cn":"牙龈；齿龈；牙床","g":"[countable, usually plural]","ex":{"en":"gum disease","cn":"牙龈病"}},{"en":"a sticky substance produced by some types of tree","cn":"树胶；树脂","g":"[uncountable]"},{"en":"a type of glue used for sticking light things together, such as paper","cn":"黏胶，胶质物（用以粘轻东西，如纸等）","g":"[uncountable]"},{"en":"a sweet that you chew (= bite many times) but do not eat","cn":"口香糖","g":"[uncountable]"},{"en":"a fairly hard, coloured sweet that tastes of fruit and that you chew","cn":"水果糖","g":"[countable]","ex":{"en":"fruit gums","cn":"水果糖"}},{"en":"to spread glue on the surface of something; to stick two things together with glue","cn":"在…上涂胶；用黏胶粘","ex":{"en":"A large address label was gummed to the package.","cn":"包装袋上贴着一大张地址签条。"},"pos":"verb"}]}},"gunshot":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（射出的）枪弹","en":"Gunshot is used to refer to bullets that are fired from a gun.","ex":{"en":"They had died of gunshot wounds.","cn":"他们死于枪伤。"}},{"pos":"N-COUNT 可数名词","cn":"枪炮射击；枪炮声","en":"A gunshot is the firing of a gun or the sound of a gun being fired.","ex":{"en":"They heard thousands of gunshots","cn":"他们听到密集的枪炮声。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the noise made by a gun when it is fired","cn":""},{"en":"the sound made by several guns being fired, especially in a war","cn":""},{"en":"the action of shooting a gun, or the sound that this makes","cn":"枪炮射击﹔枪炮声"}]},"collocations":{"phrases":["VERB + GUNSHOT hear We heard gunshots round about midnight.","GUNSHOT + NOUN wound He died of gunshot wounds to the chest.","PHRASES the noise/sound of a gunshot"]},"media":{"uk":"media/ldoce/hwd/bre/4/gunshot0205.mp3","us":"media/ldoce/hwd/ame/9/gunshot.mp3"},"examples":[{"en":"I heard the sound of gunshots out in the street.","cn":"我听到外面街上有枪炮声。"},{"en":"He was out of/within gunshot.","cn":"他在射程之外/内。"}],"oxford":{"phon":"ˈɡʌnʃɒt","pos":"noun","senses":[{"en":"the bullets that are fired from a gun","cn":"（射出的）炮弹，枪弹","g":"[uncountable]","ex":{"en":"He died of a single gunshot wound to the chest.","cn":"他死于胸部仅有的一处枪伤。"}},{"en":"the firing of a gun; the sound of it being fired","cn":"枪炮射击；枪炮声","g":"[countable]","ex":{"en":"I heard the sound of gunshots out in the street.","cn":"我听到外面街上有枪炮声。"}},{"en":"the distance that a bullet from a gun can travel","cn":"（枪炮的）射程","g":"[uncountable]","lab":"old-fashioned","ex":{"en":"He was out of gunshot.","cn":"他在射程之外。"}}]}},"gurgle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"潺潺地流；汩汩地流","en":"If water is gurgling, it is making the sound that it makes when it flows quickly and unevenly through a narrow space.","ex":{"en":"...a narrow stone-edged channel along which water gurgles unseen.","cn":"暗流潺潺的石砌狭窄水道"}},{"pos":"VERB 动词","cn":"（尤指婴儿）发咯咯声","en":"If someone, especially a baby, is gurgling, they are making a sound in their throat similar to the gurgling of water.","ex":{"en":"Henry gurgles happily in his baby chair.","cn":"亨利在婴儿椅里开心地咯咯笑。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"the sound that a liquid makes when it falls from a height, hits something hard, or is moved rapidly around","cn":""},{"en":"to make a sound like someone walking in soft, wet mud, or to move somewhere making this sound","cn":""},{"en":"if something such as a stream gurgles , it makes a low irregular sound like water flowing through a pipe","cn":""}]},"collocations":{"phrases":["ADJ. little | low","VERB + GURGLE give, let out | hear","PREP. with a ~ The water emptied with a gurgle. | ~ of He gave a low gurgle of laughter. • Note at SOUND"]},"media":{"uk":"media/ldoce/hwd/bre/5/gurgle_v0205.mp3","us":"media/ldoce/hwd/ame/b/gurgle1.mp3"},"examples":[{"en":"Water gurgled through the pipes.","cn":"水汩汩地从管道中流过。"},{"en":"a gurgling stream","cn":"潺潺溪流"}],"oxford":{"phon":"ˈɡɜːɡl","pos":"verb","senses":[{"en":"to make a sound like water flowing quickly through a narrow space","cn":"发汩汩声；发潺潺流水声","g":"[intransitive]","ex":{"en":"Water gurgled through the pipes.","cn":"水汩汩地从管道中流过。"}},{"en":"if a baby gurgles, it makes a noise in its throat when it is happy","cn":"（婴儿高兴时）发出咯咯声","g":"[intransitive]","ex":{"en":"The baby gurgled happily.","cn":"婴儿高兴地咯咯做声。"}},{"en":"a sound like water flowing quickly through a narrow space","cn":"汩汩声；潺潺声","ex":{"en":"The water emptied with a gurgle.","cn":"水汩汩地流光了。"},"pos":"noun"},{"en":"the sound that babies make in the throat, especially when they are happy","cn":"（婴儿高兴时发出的）咯咯声","ex":{"en":"The baby gave a little gurgle of laughter.","cn":"婴儿发出咯咯的笑声。"},"pos":"noun"}]}}});
